edits.text:
--night: var(--appearance-main-surface, #06111f);
--nav: var(--appearance-panel-background, #081829);
--surface: var(--appearance-main-surface, #0d1c2d);
--surface-2: var(--appearance-control, #13263a);
--line: var(--appearance-line, #26394f);
--ink: var(--appearance-ink, #f3f6fa);
--muted: var(--appearance-muted, #91a2b8);
--blue: var(--appearance-accent, #56adff);
--green: var(--appearance-play, #34ca78);
--red: var(--appearance-error, #ff575f);

/* Shared GalleryBar, Switch, Button and AnchoredMenu own control presentation. */
.settings-host .member-actions-menu { width: 220px; min-width: 0; overflow: auto; }
.settings-host .member-actions-menu .gallery-menu-action { text-decoration: none; }
.settings-host .gallery-switch.detail-setting { padding-inline: 0; }
.settings-host .gallery-switch__label small { margin-top: 4px; }
.settings-host .permission-group .gallery-switch { padding: 6px 8px; }
.settings-host .permission-group .gallery-switch:has(input:disabled) { color: var(--muted); }
.settings-host .role-note.on-page-alert { display: flex; }

.gallery-switch__track { width: 36px; height: 20px; flex: 0 0 36px; display: flex; margin-left: auto; padding: 2px; border-radius: 999px; background: #58615f; transition: background-color 150ms ease; }
.gallery-switch[aria-checked="true"] .gallery-switch__track,
.gallery-switch__input:checked + .gallery-switch__track { background: var(--appearance-play, #4bc173); }
.gallery-switch[aria-checked="true"] .gallery-switch__knob,
.gallery-switch__input:checked + .gallery-switch__track .gallery-switch__knob { transform: translateX(16px); }
.gallery-switch__knob { width: 16px; height: 16px; border-radius: 50%; background: white; box-shadow: 0 1px 4px #0008; transition: transform 150ms ease; }
.gallery-switch__control { position: relative; width: 36px; height: 20px; flex: 0 0 36px; margin-left: auto; }
.gallery-switch__control > .gallery-switch__input { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; z-index: 1; cursor: pointer; }
.gallery-switch__input:focus-visible + .gallery-switch__track { outline: 2px solid var(--appearance-interaction-outline, var(--appearance-accent, #55c7ff)); outline-offset: 2px; }
.gallery-switch:has(.gallery-switch__input:disabled) { color: var(--appearance-muted, var(--muted)); cursor: not-allowed; background: transparent; }
.gallery-switch__input:disabled { cursor: not-allowed; }
.gallery-switch__input:disabled + .gallery-switch__track { background: var(--appearance-muted, #79818b); opacity: .55; }
.gallery-switch__label { min-width: 0; white-space: normal; }
.gallery-switch__label small { display: block; color: var(--appearance-muted, var(--muted)); }
@media (prefers-reduced-motion: reduce) {
  .gallery-switch__track, .gallery-switch__knob { transition: none; }
}

const memberMenuCleanups = [];
for (const component of document.querySelectorAll('.member-actions[data-account-menu-component]')) {
  memberMenuCleanups.push(attachAccountMenu(component, { position: positionMenu, focusOnPointer: true }));

if (response.status === 401) {
  window.location.assign('/login');
  throw new Error('Session expired. Sign in again.');
}

const saved = await response.json();
if (!active) return;
const revision = form.querySelector('[name="access_revision"]');
if (assignment && (!revision || !/^[a-f0-9]{64}$/.test(saved.access_revision || ''))) {
  throw new Error('Changes were saved, but the access revision could not be refreshed. Reload this user before editing again.');
}
if (revision) revision.value = saved.access_revision;
form.dataset.initialActive = String(isActive);
form.dataset.initialLibraryAccess = String(hasAccess);
const toggle = form.querySelector('[data-admin-action="toggle-active"]');
if (toggle) (toggle.querySelector?.('.ui-button__content') || toggle).textContent = isActive ? 'Disable account' : 'Enable account';
showStatus('Changes saved.');
if (submit) submit.disabled = false;

const allowsUtilityTab = (tab) => Boolean(policy && policy.availableTabs.includes(tab));
const resolveUtilityTab = (preferred) => allowsUtilityTab(preferred)
  ? preferred : policy?.availableTabs[0] || null;
const result = Object.freeze({ allows, allowsUtilityTab, resolveUtilityTab,
  clientSurface: policy?.clientSurface || 'private_web' });

// Keyboard traversal uses native hidden state, not just CSS visibility.
document.querySelectorAll?.('[data-utility-tab]').forEach(tab => {
  tab.hidden = !allowsUtilityTab(tab.getAttribute('data-utility-tab'));
});
